  29:     static byte[] SubArray(byte[] src, int offset, int len)
  30:     {
  31:         byte[] r = new byte[len];
  32:         Array.Copy(src, offset, r, 0, len);
  33:         return r;
  34:     }
  35: 
  36:     // --- True-color (24-bit RGB) support, borrowed from the cycodca Engine/AnsiColor.cs +
  37:     // Highlighter.cs pattern (Atom One Dark palette). Falls back to the nearest 16-color
  38:     // ConsoleColor on terminals that don't advertise true-color support, and skips coloring
  39:     // entirely when output is redirected either way.
  40: 
  41:     readonly struct AnsiColor
  42:     {
  43:         public readonly byte R, G, B;
  44:         public AnsiColor(int r, int g, int b) { R = (byte)r; G = (byte)g; B = (byte)b; }
  45: 
  46:         public string FgEscape() => $"\x1b[38;2;{R};{G};{B}m";
  47:         public const string Reset = "\x1b[0m";
  48: 
  49:         public ConsoleColor ToConsoleColor()
  50:         {
  51:             var best = ConsoleColor.Gray;
  52:             var bestDist = double.MaxValue;
  53:             foreach (var (cc, cr, cg, cb) in _vgaPalette)
  54:             {
  55:                 double dr = R - cr, dg = G - cg, db = B - cb;
  56:                 double d = dr * dr + dg * dg + db * db;
  57:                 if (d < bestDist) { bestDist = d; best = cc; }
  58:             }
  59:             return best;
  60:         }
  61: 
  62:         static readonly (ConsoleColor CC, byte R, byte G, byte B)[] _vgaPalette =
  63:         {
  64:             (ConsoleColor.Black, 0, 0, 0),
  65:             (ConsoleColor.DarkBlue, 0, 0, 128),
  66:             (ConsoleColor.DarkGreen, 0, 128, 0),
  67:             (ConsoleColor.DarkCyan, 0, 128, 128),
  68:             (ConsoleColor.DarkRed, 128, 0, 0),
  69:             (ConsoleColor.DarkMagenta, 128, 0, 128),
  70:             (ConsoleColor.DarkYellow, 128, 128, 0),
  71:             (ConsoleColor.Gray, 192, 192, 192),
  72:             (ConsoleColor.DarkGray, 128, 128, 128),
  73:             (ConsoleColor.Blue, 0, 0, 255),
  74:             (ConsoleColor.Green, 0, 255, 0),
  75:             (ConsoleColor.Cyan, 0, 255, 255),
  76:             (ConsoleColor.Red, 255, 0, 0),
  77:             (ConsoleColor.Magenta, 255, 0, 255),
  78:             (ConsoleColor.Yellow, 255, 255, 0),
  79:             (ConsoleColor.White, 255, 255, 255),
  80:         };
  81:     }
  82: 
  83:     static readonly bool SupportsTrueColor = DetectTrueColor();
  84: 
  85:     static bool DetectTrueColor()
  86:     {
  87:         var colorterm = Environment.GetEnvironmentVariable("COLORTERM");
  88:         if (colorterm is "truecolor" or "24bit") return true;
  89:         if (Environment.GetEnvironmentVariable("WT_SESSION") != null) return true;
  90:         var termProg = Environment.GetEnvironmentVariable("TERM_PROGRAM");
  91:         if (termProg is "iTerm.app" or "Hyper" or "vscode") return true;
  92:         return false;
  93:     }
  94: 
  95:     static void Write(string text, AnsiColor? color = null)
  96:     {
  97:         if (color == null || Console.IsOutputRedirected)
  98:         {
  99:             Console.Write(text);
  100:             return;
  101:         }
  102: 
  103:         if (SupportsTrueColor)
  104:         {
  105:             Console.Write(color.Value.FgEscape());
  106:             Console.Write(text);
  107:             Console.Write(AnsiColor.Reset);
  108:         }
  109:         else
  110:         {
  111:             var prev = Console.ForegroundColor;
  112:             Console.ForegroundColor = color.Value.ToConsoleColor();
  113:             Console.Write(text);
  114:             Console.ForegroundColor = prev;
  115:         }
  116:     }
  117: 
  118:     static void WriteLine(string text = "", AnsiColor? color = null)
  119:     {
  120:         Write(text, color);
  121:         Console.WriteLine();
  122:     }
