  124:     // Atom One Dark palette (https://github.com/atom/one-dark-syntax), reused here to give each
  125:     // kind of token (PID, path, option name/value, env name/value, ...) a distinct, semantically
  126:     // meaningful color instead of the flat 16-color palette.
  127:     static class Colors
  128:     {
  129:         public static readonly AnsiColor Header = new(0x61, 0xAF, 0xEF);      // function (blue)
  130:         public static readonly AnsiColor Muted = new(0x5C, 0x63, 0x70);       // comment (muted blue-gray) - parens, path dir/ext
  131:         public static readonly AnsiColor Pid = new(0x98, 0xC3, 0x79);         // string (green)
  132:         public static readonly AnsiColor Name = new(0x61, 0xAF, 0xEF);        // function (blue) - process base name
  133:         public static readonly AnsiColor Subcommand = new(0xC6, 0x78, 0xDD); // keyword (purple) - first bare arg after exe
  134:         public static readonly AnsiColor OptName = new(0x56, 0xB6, 0xC2);     // operator (teal) - option prefix + name
  135:         public static readonly AnsiColor OptValue = new(0xAB, 0xB2, 0xBF);    // variable (light gray) - option value
  136:         public static readonly AnsiColor QuotedString = new(0x98, 0xC3, 0x79); // string (green) - quoted args/values
  137:         public static readonly AnsiColor EnvName = new(0xE0, 0x6C, 0x75);     // attribute (red)
  138:         public static readonly AnsiColor EnvValue = new(0xAB, 0xB2, 0xBF);    // variable (light gray)
  139:         public static readonly AnsiColor Error = new(0xE0, 0x6C, 0x75);       // attribute/red
  140:     }
