  142:     class ProcessDetails
  143:     {
  144:         public string EnvBlock = "";
  145:         public string ImagePath = "";
  146:         public string CommandLine = "";
  147:         public string CurrentDirectory = "";
  148:         public string Error = ""; // empty = no error
  149:         public int ParentPid = -1; // -1 = unknown/not read
  150:     }
  151: 
  152:     // Reads a remote UNICODE_STRING given the local copy of its containing struct (ppBuf) and
  153:     // the byte offset within it where the UNICODE_STRING (Length:2, MaximumLength:2, pad:4, Buffer:8) starts.
  154:     static string ReadRemoteUnicodeString(IntPtr h, byte[] ppBuf, int offset)
  155:     {
  156:         ushort length = BitConverter.ToUInt16(ppBuf, offset);
  157:         if (length == 0) return "";
  158: 
  159:         long bufAddr = BitConverter.ToInt64(ppBuf, offset + 8);
  160:         if (bufAddr == 0) return "";
  161: 
  162:         byte[] buf = new byte[length];
  163:         int read;
  164:         if (!ReadProcessMemory(h, new IntPtr(bufAddr), buf, length, out read) || read <= 0) return "";
  165: 
  166:         return Encoding.Unicode.GetString(buf, 0, read);
  167:     }
  168: 
  169:     static ProcessDetails GetProcessDetails(int pid)
  170:     {
  171:         var details = new ProcessDetails();
  172: 
  173:         IntPtr h = OpenProcess(0x0410, false, pid); // PROCESS_QUERY_INFORMATION | PROCESS_VM_READ
  174:         if (h == IntPtr.Zero)
  175:         {
  176:             int err = Marshal.GetLastWin32Error();
  177:             details.Error = "ERROR: OpenProcess failed, code=" + err;
  178:             return details;
  179:         }
  180:         try
  181:         {
  182:             byte[] pbi = new byte[48];
  183:             int retLen;
  184:             int status = NtQueryInformationProcess(h, 0, pbi, pbi.Length, out retLen);
  185:             if (status != 0)
  186:             {
  187:                 details.Error = "ERROR: NtQueryInformationProcess status=" + status;
  188:                 return details;
  189:             }
  190: 
  191:             IntPtr pebAddr = new IntPtr(BitConverter.ToInt64(pbi, 8));
  192: 
  193:             // PROCESS_BASIC_INFORMATION (64-bit): InheritedFromUniqueProcessId is the parent PID,
  194:             // at byte offset 40 (ExitStatus:8, PebBaseAddress:8, AffinityMask:8, BasePriority:8,
  195:             // UniqueProcessId:8, InheritedFromUniqueProcessId:8). Already have this data in pbi,
  196:             // no extra syscall needed.
  197:             details.ParentPid = (int)BitConverter.ToInt64(pbi, 40);
  198: 
  199:             byte[] pebBuf = new byte[0x150];
  200:             int read;
  201:             if (!ReadProcessMemory(h, pebAddr, pebBuf, pebBuf.Length, out read))
  202:             {
  203:                 details.Error = "ERROR: ReadProcessMemory(PEB) failed, code=" + Marshal.GetLastWin32Error();
  204:                 return details;
  205:             }
  206: 
  207:             IntPtr procParamsAddr = new IntPtr(BitConverter.ToInt64(pebBuf, 0x20));
  208: 
  209:             byte[] ppBuf = new byte[0x100];
  210:             if (!ReadProcessMemory(h, procParamsAddr, ppBuf, ppBuf.Length, out read))
  211:             {
  212:                 details.Error = "ERROR: ReadProcessMemory(ProcParams) failed, code=" + Marshal.GetLastWin32Error();
  213:                 return details;
  214:             }
  215: 
  216:             // RTL_USER_PROCESS_PARAMETERS (64-bit): CurrentDirectory.DosPath UNICODE_STRING at 0x38
  217:             // (part of the embedded CURDIR struct), ImagePathName at 0x60, CommandLine at 0x70.
  218:             details.CurrentDirectory = ReadRemoteUnicodeString(h, ppBuf, 0x38);
  219:             details.ImagePath = ReadRemoteUnicodeString(h, ppBuf, 0x60);
  220:             details.CommandLine = ReadRemoteUnicodeString(h, ppBuf, 0x70);
  221: 
  222:             IntPtr envAddr = new IntPtr(BitConverter.ToInt64(ppBuf, 0x80));
  223: 
  224:             int chunkSize = 4096;
  225:             byte[] all = new byte[0];
  226:             int totalRead = 0;
  227:             int maxTotal = 1024 * 1024;
  228:             bool foundEnd = false;
  229:             while (!foundEnd && totalRead < maxTotal)
  230:             {
  231:                 byte[] chunk = new byte[chunkSize];
  232:                 bool ok = ReadProcessMemory(h, new IntPtr(envAddr.ToInt64() + totalRead), chunk, chunkSize, out read);
  233:                 if (!ok || read == 0) break;
  234:                 byte[] newAll = new byte[all.Length + read];
  235:                 Array.Copy(all, newAll, all.Length);
  236:                 Array.Copy(chunk, 0, newAll, all.Length, read);
  237:                 all = newAll;
  238:                 totalRead += read;
  239:                 for (int i = 0; i + 3 < all.Length; i += 2)
  240:                 {
  241:                     if (all[i] == 0 && all[i + 1] == 0 && all[i + 2] == 0 && all[i + 3] == 0)
  242:                     {
  243:                         foundEnd = true;
  244:                         all = SubArray(all, 0, i + 2);
  245:                         break;
  246:                     }
  247:                 }
  248:             }
  249: 
  250:             details.EnvBlock = Encoding.Unicode.GetString(all);
  251:             return details;
  252:         }
  253:         finally
  254:         {
  255:             CloseHandle(h);
  256:         }
  257:     }
