  259:     // Parses a raw Win32 command-line string into argv, using the same rules the OS itself uses.
  260:     static string[] ParseCommandLine(string cmdLine)
  261:     {
  262:         if (string.IsNullOrEmpty(cmdLine)) return Array.Empty<string>();
  263: 
  264:         int argc;
  265:         IntPtr argv = CommandLineToArgvW(cmdLine, out argc);
  266:         if (argv == IntPtr.Zero) return Array.Empty<string>();
  267: 
  268:         try
  269:         {
  270:             var result = new string[argc];
  271:             for (int i = 0; i < argc; i++)
  272:             {
  273:                 IntPtr strPtr = Marshal.ReadIntPtr(argv, i * IntPtr.Size);
  274:                 result[i] = Marshal.PtrToStringUni(strPtr) ?? "";
  275:             }
  276:             return result;
  277:         }
  278:         finally
  279:         {
  280:             LocalFree(argv);
  281:         }
  282:     }
  283: 
  284:     // Escapes a single argument per the standard Windows CommandLineToArgvW-compatible rules:
  285:     // backslashes are only special immediately before a '"', and must be doubled there (plus one
  286:     // more to escape the quote itself); a run of backslashes at the very end of the argument
  287:     // (right before the closing quote we add) must also be doubled.
  288:     static string EscapeArgumentForWindows(string arg)
  289:     {
  290:         if (arg.Length != 0 && arg.IndexOfAny(new[] { ' ', '\t', '\n', '\v', '"' }) < 0)
  291:             return arg;
  292: 
  293:         var sb = new StringBuilder();
  294:         sb.Append('"');
  295: 
  296:         for (int i = 0; i < arg.Length; )
  297:         {
  298:             int backslashes = 0;
  299:             while (i < arg.Length && arg[i] == '\\')
  300:             {
  301:                 backslashes++;
  302:                 i++;
  303:             }
  304: 
  305:             if (i == arg.Length)
  306:             {
  307:                 sb.Append('\\', backslashes * 2);
  308:                 break;
  309:             }
  310:             else if (arg[i] == '"')
  311:             {
  312:                 sb.Append('\\', backslashes * 2 + 1);
  313:                 sb.Append('"');
  314:                 i++;
  315:             }
  316:             else
  317:             {
  318:                 sb.Append('\\', backslashes);
  319:                 sb.Append(arg[i]);
  320:                 i++;
  321:             }
  322:         }
  323: 
  324:         sb.Append('"');
  325:         return sb.ToString();
  326:     }
