  329:     static readonly string[] FilterFlags = new[]
  330:     {
  331:         "--contains", "--env-contains", "--name-contains", "--env-name-contains", "--name-starts-with", "--env-name-starts-with",
  332:         "--value-contains", "--env-value-contains", "--value-starts-with", "--env-value-starts-with"
  333:     };
  334: 
  335:     static readonly string[] BooleanFlags = new[] { "--where", "--location", "--args", "--env", "--pid", "--all", "--tree", "--cwd" };
  336: 
  337:     // --- Help-text colorizing helpers -----------------------------------------------------
  338: 
  339:     static readonly Regex InlineFlagPattern = new(@"(--[a-zA-Z][a-zA-Z0-9-]*)");
  340: 
  341:     // Highlights any --flag-looking word mentioned inline within a plain descriptive sentence.
  342:     static void WriteBodyLine(string line)
  343:     {
  344:         var parts = InlineFlagPattern.Split(line);
  345:         foreach (var part in parts)
  346:         {
  347:             if (part.StartsWith("--"))
  348:                 Write(part, Colors.OptName);
  349:             else
  350:                 Console.Write(part);
  351:         }
  352:         Console.WriteLine();
  353:     }
  354: 
  355:     static void WriteSectionHeader(string text) => WriteLine(text, Colors.Header);
  356: 
  357:     static List<string> TokenizeExample(string s)
  358:     {
  359:         var tokens = new List<string>();
  360:         int i = 0;
  361:         while (i < s.Length)
  362:         {
  363:             while (i < s.Length && s[i] == ' ') i++;
  364:             if (i >= s.Length) break;
  365: 
  366:             int start = i;
  367:             if (s[i] == '\'' || s[i] == '"')
  368:             {
  369:                 char q = s[i];
  370:                 i++;
  371:                 while (i < s.Length && s[i] != q) i++;
  372:                 if (i < s.Length) i++;
  373:             }
  374:             else
  375:             {
  376:                 while (i < s.Length && s[i] != ' ') i++;
  377:             }
  378:             tokens.Add(s.Substring(start, i - start));
  379:         }
  380:         return tokens;
  381:     }
  382: 
  383:     // Colors a single example-command token using the same semantic rules as real px output:
  384:     // quoted tokens -> QuotedString, numeric -> Pid, flags -> OptName(+OptValue), bare words
  385:     // before the first flag -> Subcommand (process name/fragment target), bare words after
  386:     // the first flag -> OptValue (a value belonging to the preceding flag).
  387:     static void WriteExampleToken(string arg, ref bool seenOption)
  388:     {
  389:         if (arg.Length >= 2 && (arg[0] == '\'' || arg[0] == '"') && arg[^1] == arg[0])
  390:         {
  391:             Write(arg, Colors.QuotedString);
  392:             return;
  393:         }
  394: 
  395:         if (int.TryParse(arg, out _))
  396:         {
  397:             Write(arg, Colors.Pid);
  398:             return;
  399:         }
  400: 
  401:         bool isOption = arg.StartsWith("--") || arg.StartsWith("/") || arg.StartsWith("-");
  402:         if (!isOption)
  403:         {
  404:             Write(arg, seenOption ? Colors.OptValue : Colors.Subcommand);
  405:             return;
  406:         }
  407: 
  408:         seenOption = true;
  409:         int splitAt = arg.IndexOfAny(new[] { '=', ':' });
  410:         string namePart = splitAt >= 0 ? arg.Substring(0, splitAt) : arg;
  411:         string valuePart = splitAt >= 0 ? arg.Substring(splitAt) : "";
  412: 
  413:         Write(namePart, Colors.OptName);
  414:         if (valuePart.Length > 0)
  415:         {
  416:             Write(valuePart.Substring(0, 1), Colors.Muted);
  417:             Write(valuePart.Substring(1), Colors.OptValue);
  418:         }
  419:     }
  420: 
  421:     // Writes one fully-colorized "  px ... " example line, with an optional trailing
  422:     // "(explanatory comment)" rendered in the muted comment color.
  423:     static void WriteExampleLine(string command, string comment = "")
  424:     {
  425:         Write("  ");
  426:         var tokens = TokenizeExample(command);
  427:         bool seenOption = false;
  428:         for (int i = 0; i < tokens.Count; i++)
  429:         {
  430:             if (i > 0) Write(" ");
  431:             if (i == 0) { Write(tokens[i], Colors.Name); continue; } // "px" itself
  432:             WriteExampleToken(tokens[i], ref seenOption);
  433:         }
  434: 
  435:         if (!string.IsNullOrEmpty(comment))
  436:         {
  437:             Write("    ");
  438:             Write(comment, Colors.Muted);
  439:         }
  440: 
  441:         Console.WriteLine();
  442:     }
  443: 
  444:     static void PrintUsage()
  445:     {
  446:         WriteLine("px - inspect running processes: list PIDs, exe paths, command lines, and env vars", Colors.Header);
  447:         Console.WriteLine();
  448:         WriteSectionHeader("USAGE:");
  449:         Console.WriteLine("  px <pid|process-name|name-fragment> [...] [<filter-value> ...] [<filter-flag> <value> [<value> ...]] ...");
  450:         Console.WriteLine("  px <pid> shell");
  451:         Console.WriteLine("  px <pid> run [--] <command> [<arg> ...]");
  452:         Console.WriteLine("  px <pid> rerun");
  453:         Console.WriteLine();
  454:         WriteSectionHeader("PROCESS ACTIONS:");
  455:         Console.WriteLine("  shell   start the nearest shell found in the process ancestry, using the target");
  456:         Console.WriteLine("          process's current directory and environment");
  457:         Console.WriteLine("  run     run a command using the target process's current directory and environment;");
  458:         Console.WriteLine("          the conventional -- separator is supported but optional");
  459:         Console.WriteLine("  rerun   run the target's original executable and arguments again, using its current");
  460:         Console.WriteLine("          directory and environment");
  461:         Console.WriteLine();
  462:         WriteSectionHeader("HOW PROCESS TARGETS ARE RESOLVED (in order):");
  463:         Console.WriteLine("  1. Numeric token           -> treated as a PID");
  464:         Console.WriteLine("  2. Exact process name match -> that process (case-insensitive)");
  465:         Console.WriteLine("  3. Token has '*' or '?'     -> glob match against process names (e.g. 'cyco*')");
  466:         Console.WriteLine("  4. If NOTHING matched yet   -> try remaining tokens as name substrings (e.g. 'chrome')");
  467:         Console.WriteLine();
  468:         WriteSectionHeader("HOW LEFTOVER TOKENS BECOME ENV-VAR FILTERS:");
  469:         Console.WriteLine("  Once at least one process target is resolved, any leftover token filters env vars");
  470:         Console.WriteLine("  by NAME, in this order:");
  471:         Console.WriteLine("    1. Token has '*' or '?'        -> glob match against variable names");
  472:         Console.WriteLine("    2. Exact match (case-sensitive) -> used if one exists");
  473:         Console.WriteLine("    3. Exact match (case-insensitive) -> used only if no case-sensitive match exists");
  474:         Console.WriteLine("    (no substring/prefix guessing otherwise)");
  475:         Console.WriteLine();
  476:         WriteSectionHeader("OTHER FLAGS:");
  477:         WriteBodyLine("  --pid       always show (PID) on the main line, even with --location/--args");
  478:         WriteBodyLine("  --location  show the full path to each process's executable");
  479:         WriteBodyLine("  --args      show the process's command-line args (fancy-colored) on the main line");
  480:         WriteBodyLine("  --env       after everything else, show ALL environment variables for each process");
  481:         WriteBodyLine("  --all       also show processes with no matching environment variables (see below)");
  482:         WriteBodyLine("  --tree      show each matched process's full ancestry as a real tree (see below)");
  483:         WriteBodyLine("  --cwd       show the process's current working directory right on its main line");
  484:         WriteBodyLine("  --where     alias for BOTH --location AND --cwd together (\"where\" the thing is, and");
  485:         WriteBodyLine("              \"where\" it's running)");
  486:         Console.WriteLine();
  487:         WriteBodyLine("  By default (neither --location nor --args) the main line is '(PID)  name.exe'.");
  488:         WriteBodyLine("  --location alone shows the full path instead of the PID/name. --args alone shows");
  489:         WriteBodyLine("  'name.exe <args>' instead of the PID. Add --pid to force the PID to show either way.");
  490:         WriteBodyLine("  If BOTH --location and --args are given, the main line is 'name.exe <args>' and the");
  491:         WriteBodyLine("  full path is shown on its own indented line underneath. --cwd appends '  (<cwd>)' right");
  492:         WriteBodyLine("  on the main line, after the args (or after the base name if no args) - this also means");
  493:         WriteBodyLine("  it shows up per-node when combined with --tree.");
  494:         Console.WriteLine();
  495:         WriteSectionHeader("TREE MODE (--tree):");
  496:         WriteBodyLine("  Walks each matched process's ancestry (parent, grandparent, etc.) as far as it can be");
  497:         WriteBodyLine("  traced, merging shared ancestors so two matched processes under the same parent appear");
  498:         WriteBodyLine("  as two branches of one tree, not two separate trees. Distinct ancestries with no common");
  499:         WriteBodyLine("  ancestor are printed as separate root trees (a forest), each block separated by a blank");
  500:         WriteBodyLine("  line. Matched PIDs are shown in the PID color; ancestor-only PIDs are muted. If --args");
  501:         WriteBodyLine("  is also given, each tree node shows its command-line args too.");
  502:         Console.WriteLine();
  503:         WriteBodyLine("  A matched process whose parent has already exited (or has no parent at all) isn't");
  504:         WriteBodyLine("  shown as a trivial one-node tree - instead it's listed at the end with either");
  505:         WriteBodyLine("  '(dead parent <PID>)' (in red) or '(no parent)'.");
  506:         Console.WriteLine();
