  552:     static string GetProcessNameSafe(int pid)
  553:     {
  554:         try
  555:         {
  556:             return Process.GetProcessById(pid).ProcessName;
  557:         }
  558:         catch
  559:         {
  560:             return "?";
  561:         }
  562:     }
  563: 
  564:     // Cached once per run: the full snapshot of currently-running PIDs, from Process.GetProcesses().
  565:     // Used instead of opening each individual process handle to check aliveness, since
  566:     // Process.GetProcessById(pid).HasExited requires SYNCHRONIZE access - which can be denied for
  567:     // protected/system processes (e.g. a SYSTEM-owned svchost.exe) even when they ARE alive,
  568:     // causing them to be misreported as "exited" (dead parent) when they're not.
  569:     static readonly Lazy<HashSet<int>> LivePids = new(() =>
  570:         new HashSet<int>(Process.GetProcesses().Select(p => p.Id)));
  571: 
  572:     static bool IsProcessAlive(int pid) => LivePids.Value.Contains(pid);
  573: 
  574:     // Lightweight parent-PID lookup for ancestor-chain walking (--parents N/all): only opens
  575:     // the process and reads PROCESS_BASIC_INFORMATION, skipping the PEB/env-block work that
  576:     // GetProcessDetails does for the primary matched processes. Returns -1 on any failure.
  577:     static int GetParentPidOnly(int pid)
  578:     {
  579:         IntPtr h = OpenProcess(0x0400, false, pid); // PROCESS_QUERY_INFORMATION
  580:         if (h == IntPtr.Zero) return -1;
  581:         try
  582:         {
  583:             byte[] pbi = new byte[48];
  584:             int retLen;
  585:             int status = NtQueryInformationProcess(h, 0, pbi, pbi.Length, out retLen);
  586:             if (status != 0) return -1;
  587:             return (int)BitConverter.ToInt64(pbi, 40);
  588:         }
  589:         finally
  590:         {
  591:             CloseHandle(h);
  592:         }
  593:     }
