  597:     // Named entry type for a resolved+filtered process, replacing the anonymous type previously
  598:     // returned by the LINQ projection - needed so tree mode can reference matched entries by PID
  599:     // when building the ancestor forest.
  600:     class MatchedEntry
  601:     {
  602:         public int Pid;
  603:         public ProcessDetails Details = new();
  604:         public string ShortName = "";
  605:         public string[] RestArgs = Array.Empty<string>();
  606:         public string Cwd = "";
  607:         public string SortKey = "";
  608:         public (string Raw, string Name, string Value)[] ParsedVars = Array.Empty<(string, string, string)>();
  609:         public int EnvMatchCount;
  610:     }
