  612:     class ParsedArgs
  613:     {
  614:         public SortedSet<int> Pids = new SortedSet<int>();
  615:         public List<string> Contains = new List<string>();
  616:         public List<string> NameContains = new List<string>();
  617:         public List<string> NameStartsWith = new List<string>();
  618:         public List<string> ValueContains = new List<string>();
  619:         public List<string> ValueStartsWith = new List<string>();
  620:         public bool ShowLocation = false;
  621:         public bool ShowArgs = false;
  622:         public bool ShowEnvExplicit = false;
  623:         public bool ShowPidExplicit = false;
  624:         public bool ShowAll = false;
  625:         public bool ShowTree = false;
  626:         public bool ShowCwd = false;
  627: 
  628:         // Leftover tokens (not resolved to a process): matched against env var NAMES using
  629:         // an exact-first progression (see CompileImplicitFilters), NOT contains/starts-with,
  630:         // unless the token itself contains '*'/'?'.
  631:         public List<string> ImplicitFilters = new List<string>();
  632:         public List<string> UnresolvedTargets = new List<string>();
  633: 
  634:         public bool HasFilters =>
  635:             Contains.Count > 0 ||
  636:             NameContains.Count > 0 || NameStartsWith.Count > 0 ||
  637:             ValueContains.Count > 0 || ValueStartsWith.Count > 0 ||
  638:             ImplicitFilters.Count > 0;
  639: 
  640:         // Env vars are shown if --env was given explicitly, OR any env filter (implicit or
  641:         // explicit --env-*) was given - filters imply you want to see the (filtered) env vars.
  642:         public bool ShouldShowEnv => ShowEnvExplicit || HasFilters;
  643: 
  644:         // When --env is given with NO filters at all, show everything (unfiltered).
  645:         public bool ShowEnvAll => ShowEnvExplicit && !HasFilters;
  646:     }
  647: 
  648:     // Process.ProcessName never includes the ".exe" extension, so strip a trailing ".exe"
  649:     // (case-insensitive) from a token before comparing it against process names - lets
  650:     // 'px cycod.exe' work the same as 'px cycod'.
  651:     static string StripExeSuffix(string arg) =>
  652:         arg.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) ? arg.Substring(0, arg.Length - 4) : arg;
  653: 
  654:     static Regex GlobToRegex(string glob)
  655:     {
  656:         var sb = new StringBuilder("^");
  657:         foreach (var c in glob)
  658:         {
  659:             if (c == '*') sb.Append(".*");
  660:             else if (c == '?') sb.Append('.');
  661:             else sb.Append(Regex.Escape(c.ToString()));
  662:         }
  663:         sb.Append('$');
  664:         return new Regex(sb.ToString(), RegexOptions.IgnoreCase);
  665:     }
  666: 
  667:     static ParsedArgs ParseArgs(string[] args)
  668:     {
  669:         var result = new ParsedArgs();
  670:         var allProcesses = Process.GetProcesses();
  671:         var pending = new List<string>();
  672: 
  673:         // Pass 1: handle filter flags, numeric PIDs, and exact process-name matches
  674:         // immediately (these are unambiguous). Anything else is deferred to "pending".
  675:         int i = 0;
  676:         while (i < args.Length)
  677:         {
  678:             var arg = args[i];
  679: 
  680:             var argLower = arg.ToLowerInvariant();
  681: 
  682:             if (argLower == "--location")
  683:             {
  684:                 result.ShowLocation = true;
  685:                 i++;
  686:                 continue;
  687:             }
  688: 
  689:             if (argLower == "--where")
  690:             {
  691:                 // --where is an alias for BOTH --location and --cwd: "where" the thing IS
  692:                 // (its exe path) and "where" it's running (its current working directory).
  693:                 result.ShowLocation = true;
  694:                 result.ShowCwd = true;
  695:                 i++;
  696:                 continue;
  697:             }
  698: 
  699:             if (argLower == "--args")
  700:             {
  701:                 result.ShowArgs = true;
  702:                 i++;
  703:                 continue;
  704:             }
  705: 
  706:             if (argLower == "--env")
  707:             {
  708:                 result.ShowEnvExplicit = true;
  709:                 i++;
  710:                 continue;
  711:             }
  712: 
  713:             if (argLower == "--pid")
  714:             {
  715:                 result.ShowPidExplicit = true;
  716:                 i++;
  717:                 continue;
  718:             }
  719: 
  720:             if (argLower == "--all")
  721:             {
  722:                 result.ShowAll = true;
  723:                 i++;
  724:                 continue;
  725:             }
  726: 
  727:             if (argLower == "--tree")
  728:             {
  729:                 result.ShowTree = true;
  730:                 i++;
  731:                 continue;
  732:             }
  733: 
  734:             if (argLower == "--cwd")
  735:             {
  736:                 result.ShowCwd = true;
  737:                 i++;
  738:                 continue;
  739:             }
  740: 
  741:             if (Array.IndexOf(FilterFlags, argLower) >= 0)
  742:             {
  743:                 var target = arg.ToLowerInvariant() switch
  744:                 {
  745:                     "--contains" or "--env-contains" => result.Contains,
  746:                     "--name-contains" or "--env-name-contains" => result.NameContains,
  747:                     "--name-starts-with" or "--env-name-starts-with" => result.NameStartsWith,
  748:                     "--value-contains" or "--env-value-contains" => result.ValueContains,
  749:                     "--value-starts-with" or "--env-value-starts-with" => result.ValueStartsWith,
  750:                     _ => null
  751:                 };
  752:                 i++;
  753:                 while (i < args.Length &&
  754:                        Array.IndexOf(FilterFlags, args[i].ToLowerInvariant()) < 0 &&
  755:                        Array.IndexOf(BooleanFlags, args[i].ToLowerInvariant()) < 0)
  756:                 {
  757:                     target!.Add(args[i]);
  758:                     i++;
  759:                 }
  760:                 continue;
  761:             }
  762: 
  763:             int pid;
  764:             if (int.TryParse(arg, out pid))
  765:             {
  766:                 result.Pids.Add(pid);
  767:                 i++;
  768:                 continue;
  769:             }
  770: 
  771:             if (arg.IndexOf('*') >= 0 || arg.IndexOf('?') >= 0)
  772:             {
  773:                 // Explicit wildcard: try it as a process-name glob first (unconditionally,
  774:                 // regardless of whether other exact matches already exist). If it matches
  775:                 // zero processes, don't discard it - let it fall through to "pending" so it
  776:                 // can still be used as an env-var-name glob filter (e.g. 'CYCODD_*').
  777:                 var regex = GlobToRegex(StripExeSuffix(arg));
  778:                 var globMatches = allProcesses.Where(p => regex.IsMatch(p.ProcessName)).ToArray();
  779:                 if (globMatches.Length > 0)
  780:                 {
  781:                     foreach (var p in globMatches) result.Pids.Add(p.Id);
  782:                     i++;
  783:                     continue;
  784:                 }
  785: 
  786:                 pending.Add(arg);
  787:                 i++;
  788:                 continue;
  789:             }
  790: 
  791:             var exactMatches = allProcesses.Where(p => string.Equals(p.ProcessName, StripExeSuffix(arg), StringComparison.OrdinalIgnoreCase)).ToArray();
  792:             if (exactMatches.Length > 0)
  793:             {
  794:                 foreach (var p in exactMatches) result.Pids.Add(p.Id);
  795:                 i++;
  796:                 continue;
  797:             }
  798: 
  799:             pending.Add(arg);
  800:             i++;
  801:         }
  802: 
  803:         // Pass 2: if we already have definite targets (from PIDs or exact name matches),
  804:         // any remaining "pending" tokens are unambiguously filters - no fragment stealing.
  805:         // Only if we have NO definite targets yet do we fall back to fragment/substring
  806:         // matching against process names, so a lone token like "chrome" still works.
  807:         if (result.Pids.Count == 0)
  808:         {
  809:             var stillPending = new List<string>();
  810:             foreach (var arg in pending)
  811:             {
  812:                 var substringMatches = allProcesses.Where(p => p.ProcessName.IndexOf(StripExeSuffix(arg), StringComparison.OrdinalIgnoreCase) >= 0).ToArray();
  813:                 if (substringMatches.Length > 0)
  814:                     foreach (var p in substringMatches) result.Pids.Add(p.Id);
  815:                 else
  816:                     stillPending.Add(arg);
  817:             }
  818:             pending = stillPending;
  819:         }
  820: 
  821:         foreach (var arg in pending)
  822:         {
  823:             result.ImplicitFilters.Add(arg);
  824:             result.UnresolvedTargets.Add(arg);
  825:         }
  826: 
  827:         return result;
  828:     }
  829: 
  830:     // For each implicit (leftover) filter token, decide its match strategy against the
  831:     // ACTUAL variable names of one specific process:
  832:     //   1. Token has '*' or '?'  -> glob match (case-insensitive), can match multiple names.
  833:     //   2. Else, if some var name equals the token exactly (case-sensitive)  -> use that,
  834:     //      i.e. do NOT fall back to case-insensitive matching.
  835:     //   3. Else, if some var name equals the token exactly (case-insensitive) -> use that.
  836:     //   4. Else -> token matches nothing for this process (no contains/starts-with fallback).
  837:     static List<Func<string, bool>> CompileImplicitFilters(List<string> tokens, string[] varNames)
  838:     {
  839:         var predicates = new List<Func<string, bool>>();
  840:         foreach (var token in tokens)
  841:         {
  842:             if (token.IndexOf('*') >= 0 || token.IndexOf('?') >= 0)
  843:             {
  844:                 var regex = GlobToRegex(token);
  845:                 predicates.Add(name => regex.IsMatch(name));
  846:                 continue;
  847:             }
  848: 
  849:             var t = token;
  850:             if (varNames.Any(n => string.Equals(n, t, StringComparison.Ordinal)))
  851:             {
  852:                 predicates.Add(name => string.Equals(name, t, StringComparison.Ordinal));
  853:                 continue;
  854:             }
  855: 
  856:             if (varNames.Any(n => string.Equals(n, t, StringComparison.OrdinalIgnoreCase)))
  857:             {
  858:                 predicates.Add(name => string.Equals(name, t, StringComparison.OrdinalIgnoreCase));
  859:                 continue;
  860:             }
  861: 
  862:             predicates.Add(name => false);
  863:         }
  864:         return predicates;
  865:     }
  866: 
  867:     static bool PassesFilters(ParsedArgs parsed, string name, string value, List<Func<string, bool>> compiledImplicit)
  868:     {
  869:         if (!parsed.HasFilters)
  870:             return true;
  871: 
  872:         if (parsed.Contains.Any(f => name.IndexOf(f, StringComparison.OrdinalIgnoreCase) >= 0 || value.IndexOf(f, StringComparison.OrdinalIgnoreCase) >= 0)) return true;
  873:         if (parsed.NameContains.Any(f => name.IndexOf(f, StringComparison.OrdinalIgnoreCase) >= 0)) return true;
  874:         if (parsed.NameStartsWith.Any(f => name.StartsWith(f, StringComparison.OrdinalIgnoreCase))) return true;
  875:         if (parsed.ValueContains.Any(f => value.IndexOf(f, StringComparison.OrdinalIgnoreCase) >= 0)) return true;
  876:         if (parsed.ValueStartsWith.Any(f => value.StartsWith(f, StringComparison.OrdinalIgnoreCase))) return true;
  877:         if (compiledImplicit.Any(p => p(name))) return true;
  878: 
  879:         return false;
  880:     }
  881: 
  882:     // Writes a filesystem path with the directory portion and file extension muted, and just
  883:     // the filename's base (no dir, no extension) in the "Name" color -
  884:     // e.g. C:\dir\ (muted) cycod (blue) .exe (muted).
  885:     static void WriteExePathColored(string display)
  886:     {
  887:         int lastSlash = display.LastIndexOfAny(new[] { '\\', '/' });
  888:         string dirPart = lastSlash >= 0 ? display.Substring(0, lastSlash + 1) : "";
  889:         string fileName = lastSlash >= 0 ? display.Substring(lastSlash + 1) : display;
  890: 
  891:         int lastDot = fileName.LastIndexOf('.');
  892:         string baseName = lastDot > 0 ? fileName.Substring(0, lastDot) : fileName;
  893:         string ext = lastDot > 0 ? fileName.Substring(lastDot) : "";
  894: 
  895:         Write(dirPart, Colors.Muted);
  896:         Write(baseName, Colors.Name);
  897:         Write(ext, Colors.Muted);
  898:     }
  899: 
  900:     // Writes a single already-escaped command-line argument with "fancy" One-Dark-inspired
  901:     // coloring, tracking a single "seenOption" phase flag across the whole arg list:
  902:     //   - quoted args (start with '"')                -> always QuotedString (green), in
  903:     //                                                     either phase
  904:     //   - before the FIRST -, --, or / prefixed arg    -> bare/unquoted args are the leading
  905:     //                                                     "noun/verb" run (e.g. 'cycodd start')
  906:     //                                                     -> Subcommand (purple)
  907:     //   - once any -, --, or / prefixed arg is seen    -> we're in "option land" from then on:
  908:     //       - prefixed args   -> prefix+name in OptName (blue), value after '='/':' in
  909:     //                            OptValue (orange), or QuotedString if that value is quoted
  910:     //       - bare args       -> treated as a value for the preceding option (e.g. 'en-US'
  911:     //                            after '--lang') -> OptValue (orange)
  912:     static void WriteArgColored(string arg, ref bool seenOption)
  913:     {
  914:         if (arg.StartsWith("\""))
  915:         {
  916:             Write(arg, Colors.QuotedString);
  917:             return;
  918:         }
  919: 
  920:         bool isOption = arg.StartsWith("--") || arg.StartsWith("/") || arg.StartsWith("-");
  921: 
  922:         if (!isOption)
  923:         {
  924:             Write(arg, seenOption ? Colors.OptValue : Colors.Subcommand);
  925:             return;
  926:         }
  927: 
  928:         seenOption = true;
  929: 
  930:         int splitAt = arg.IndexOfAny(new[] { '=', ':' });
  931:         string namePart = splitAt >= 0 ? arg.Substring(0, splitAt) : arg;
  932:         string valuePart = splitAt >= 0 ? arg.Substring(splitAt) : "";
  933: 
  934:         Write(namePart, Colors.OptName);
  935:         if (valuePart.Length > 0)
  936:         {
  937:             var sep = valuePart[0];
  938:             var valueRest = valuePart.Substring(1);
  939:             Write(sep.ToString(), Colors.Muted);
  940:             Write(valueRest, valueRest.StartsWith("\"") ? Colors.QuotedString : Colors.OptValue);
  941:         }
  942:     }
