  955: 
  956:     // --- Tree mode (--tree): build a real ancestry tree/forest out of the matched PIDs -------
  957:     //
  958:     // For each matched PID, walk up via GetParentPidOnly() until we hit a PID that's exited
  959:     // (dead parents are NOT included as nodes - we simply treat that PID as if it had no
  960:     // parent at all, since there's nothing meaningful left to show about it), has no further
  961:     // parent, or that we've already seen (cycle guard). Any PID visited along the way (matched
  962:     // or merely a still-alive ancestor) becomes a node; nodes are merged by PID so that two
  963:     // matched processes sharing an ancestor produce ONE tree with two leaves, not two separate
  964:     // trees. The result is a forest: one root per distinct ancestry line that has no further
  965:     // living parent to climb to. Roots that have at least one child are printed as trees, each
  966:     // separated by a blank line. Matched PIDs that end up as childless roots (no live parent,
  967:     // and nothing else chains up through them) are NOT printed as their own trivial one-node
  968:     // trees - they're collected and listed separately at the end under "no parent".
  969: 
  970:     class TreeNode
  971:     {
  972:         public int Pid;
  973:         public bool IsMatched;      // true if this PID is one of the original matched/filtered entries
  974:         public string Name = "";
  975:         public string[] RestArgs = Array.Empty<string>();
  976:         public string Cwd = "";
  977:         public bool HasParent = false;
  978:         public int? DeadParentPid = null; // set when a parent PID was found but has since exited
  979:         public List<TreeNode> Children = new();
  980:     }
  981: 
  982:     static (List<TreeNode> Trees, List<TreeNode> NoParent) BuildForest(MatchedEntry[] entries, bool includeArgs, bool includeCwd)
  983:     {
  984:         var nodesByPid = new Dictionary<int, TreeNode>();
  985: 
  986:         TreeNode GetOrCreateNode(int pid)
  987:         {
  988:             if (nodesByPid.TryGetValue(pid, out var existing)) return existing;
  989:             var node = new TreeNode { Pid = pid };
  990:             nodesByPid[pid] = node;
  991:             return node;
  992:         }
  993: 
  994:         foreach (var e in entries)
  995:         {
  996:             var node = GetOrCreateNode(e.Pid);
  997:             node.IsMatched = true;
  998:             node.Name = e.ShortName;
  999:             node.RestArgs = e.RestArgs;
  1000:             node.Cwd = e.Cwd;
  1001:         }
  1002: 
  1003:         // Walk up from each matched PID, linking parent/child as we go, until we hit a dead
  1004:         // (exited) parent - recorded on the child as DeadParentPid but not added as a node in
  1005:         // its own right, since there's nothing meaningful left to show about it - a PID with
  1006:         // no further parent, or one we've already climbed through (cycle guard against PID reuse).
  1007:         foreach (var e in entries)
  1008:         {
  1009:             var child = nodesByPid[e.Pid];
  1010:             var visited = new HashSet<int> { child.Pid };
  1011: 
  1012:             while (!child.HasParent)
  1013:             {
